<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Private Gmail</title>
<style>
  body { font: 16px/1.5 system-ui, sans-serif; max-width: 42rem; margin: 2rem auto; padding: 0 1rem; }
  button { font: inherit; padding: .5rem 1rem; }
  li { margin: .75rem 0; }
  .from { color: #666; font-size: .9em; }
  #status { color: #666; }
</style>
</head>
<body>
<h1>Private Gmail</h1>
<p>Everything here runs in your browser. The token goes from Google to this page and nowhere else; there is no server.</p>
<button id="signin" disabled>Connect Gmail</button>
<p id="status">Loading Google sign-in…</p>
<ul id="list"></ul>

<script>
  // Public value: safe to commit. Paste the client ID from the Cloud Console.
  const CLIENT_ID = 'PASTE_CLIENT_ID_HERE.apps.googleusercontent.com';
  const SCOPE = 'https://www.googleapis.com/auth/gmail.readonly';
  // To also keep hidden per-app data in the user's Drive, append:
  //   ' https://www.googleapis.com/auth/drive.appdata'

  const statusEl = document.getElementById('status');
  const listEl = document.getElementById('list');
  const btn = document.getElementById('signin');
  let tokenClient;

  async function gmail(path, token) {
    const r = await fetch('https://gmail.googleapis.com/gmail/v1/users/me/' + path, {
      headers: { Authorization: 'Bearer ' + token },
    });
    if (!r.ok) throw new Error(path + ' → ' + r.status);
    return r.json();
  }

  async function showRecent(token) {
    statusEl.textContent = 'Fetching…';
    const { messages = [] } = await gmail('messages?maxResults=10', token);
    const metas = await Promise.all(messages.map(m =>
      gmail('messages/' + m.id + '?format=metadata&metadataHeaders=Subject&metadataHeaders=From', token)));
    listEl.replaceChildren(...metas.map(m => {
      const h = n => (m.payload.headers.find(x => x.name === n) || {}).value || '';
      const li = document.createElement('li');
      const subj = document.createElement('div');
      subj.textContent = h('Subject') || '(no subject)';
      const from = document.createElement('div');
      from.className = 'from';
      from.textContent = h('From');
      li.append(subj, from);
      return li;
    }));
    statusEl.textContent = 'Fetched ' + metas.length + ' messages. Nothing was sent anywhere but Google.';
  }

  function init() {
    tokenClient = google.accounts.oauth2.initTokenClient({
      client_id: CLIENT_ID,
      scope: SCOPE,
      callback: resp => {
        if (resp.error) { statusEl.textContent = 'Error: ' + resp.error; return; }
        showRecent(resp.access_token).catch(e => { statusEl.textContent = String(e); });
      },
    });
    btn.disabled = false;
    btn.onclick = () => tokenClient.requestAccessToken();
    statusEl.textContent = 'Ready.';
  }
</script>
<script src="https://accounts.google.com/gsi/client" async defer onload="init()"></script>
</body>
</html>
